    """
    find the right formatting function for the dtype_

    The options dict is unpacked so that float rendering parameters
    (precision, floatmode, suppress, sign) are forwarded individually
    to _get_formatdict. Layout parameters (linewidth, edgeitems, threshold)
    and display strings (nanstr, infstr) are also forwarded for formatters
    that need them.
    """
    dtype_ = data.dtype
    dtypeobj = dtype_.type
    formatdict = _get_formatdict(
        data,
        precision=options['precision'],
        floatmode=options['floatmode'],
        suppress=options['suppress'],
        sign=options['sign'],
        legacy=options['legacy'],
        formatter=options.get('formatter'),
        nanstr=options.get('nanstr', 'nan'),
        infstr=options.get('infstr', 'inf'),
    )
